'use strict';
(() => {
 const get=id=>document.getElementById(id),TOKEN='[LINK DELLA LOCANDINA]';
 const message=`🔥 PROMO DEL GIORNO BALAC!\n\nÈ online la nuova offerta dedicata 🚗🔧\n\n👉 Visualizza la locandina con tutti i dettagli:\n${TOKEN}\n\n📲 Per maggiori informazioni, contattaci!`;
 let linkBefore='',pendingId='',popup=null,fingerprint=JSON.stringify(snapshot()),busy=false;
 function valid(value){try{const u=new URL(value.trim());return u.protocol==='https:'&&['postimg.cc','postimages.org','i.postimg.cc'].includes(u.hostname)&&u.pathname!=='/'?u.href:null}catch{return null}}
 function extract(value){return (String(value).match(/https:\/\/[^\s"'<>\[\]]+/g)||[]).map(valid).find(link=>link&&new URL(link).hostname==='postimg.cc')||null}
 function apply(link){const checked=valid(link);if(!checked)return false;const text=get('singleBroadcast').value;get('singleBroadcast').value=linkBefore&&text.includes(linkBefore)?text.replace(linkBefore,checked):text.includes(TOKEN)?text.replace(TOKEN,checked):text+'\n\n'+checked;get('singleLink').value=checked;get('singleLink').setCustomValidity('');linkBefore=checked;return true}
 function reset(){if(linkBefore)get('singleBroadcast').value=get('singleBroadcast').value.replace(linkBefore,TOKEN);linkBefore='';pendingId='';get('singleLink').value='';get('singleStatus').textContent='Locandina modificata: crea un nuovo link Postimages.';try{localStorage.removeItem('balac-postimages-pending');localStorage.removeItem('balac-postimages-result')}catch{}}
 window.CidaStudioRendered=()=>{const next=JSON.stringify(snapshot());if(next!==fingerprint){fingerprint=next;reset()}};
 function finish(id,text){if(id!==pendingId)return false;const link=extract(text);if(!link||!apply(link)){get('singleFallback').open=true;return false}pendingId='';get('singleStatus').textContent='Link BALAC inserito nel messaggio: puoi copiarlo.';try{localStorage.removeItem('balac-postimages-pending');localStorage.removeItem('balac-postimages-result')}catch{}toast('Link BALAC recuperato.');return true}
 window.CidaPostimagesReturn=finish;
 get('singlePostimages').onclick=async()=>{if(busy)return;if(!base.complete||!base.naturalWidth){toast('Attendi il caricamento del modello.');return}render();pendingId='balac_single_'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'_'+Math.random().toString(36).slice(2));const returnUrl=new URL(location.href);returnUrl.hash='';returnUrl.searchParams.delete('postimage_id');returnUrl.searchParams.delete('postimage_text');const params=new URLSearchParams({mode:'phpbb3',areaid:pendingId,hash:'1',pm:'1',lang:'italian',code:'thumb',forumurl:encodeURIComponent(returnUrl.href)});try{localStorage.setItem('balac-postimages-pending',JSON.stringify({id:pendingId,createdAt:Date.now()}));localStorage.removeItem('balac-postimages-result')}catch{}if(popup&&!popup.closed)popup.close();popup=window.open('https://postimages.org/upload?'+params,'balac_postimages_upload','scrollbars=yes,resizable=yes,width=1000,height=720');if(!popup){get('singleFallback').open=true;toast('Consenti la finestra Postimages o usa il caricamento alternativo.');return}busy=true;get('singlePostimages').disabled=true;try{const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Impossibile creare il JPG.')),'image/jpeg',.95));download(blob,filename()+'.jpg');get('singleStatus').textContent='Locandina BALAC scaricata. Seleziona questo JPG nella finestra Postimages, poi crea il link.';}catch(e){toast(e.message)}finally{busy=false;get('singlePostimages').disabled=false}};
 window.addEventListener('message',event=>{if(event.origin!=='https://postimages.org'||event.source!==popup)return;const data=event.data;if(!data||data.id!==pendingId||typeof data.message!=='string')return;try{finish(data.id,decodeURIComponent(data.message))}catch{}});
 window.addEventListener('storage',event=>{if(event.key!=='balac-postimages-result'||!event.newValue)return;try{const data=JSON.parse(event.newValue);finish(data.id,data.message)}catch{}});
 get('singleLink').addEventListener('change',()=>{const text=get('singleLink').value.trim();if(!text){reset();return}if(!apply(text)){get('singleLink').setCustomValidity('Inserisci un link HTTPS valido di Postimages.');get('singleLink').reportValidity()}});
 get('singleCopy').onclick=async()=>{if(!apply(get('singleLink').value)){toast('Genera o incolla il link Postimages prima di copiare.');return}try{await navigator.clipboard.writeText(get('singleBroadcast').value);toast('Messaggio BALAC copiato.')}catch{get('singleBroadcast').focus();get('singleBroadcast').select();toast('Testo selezionato: premi Ctrl+C o usa Copia.')}};
 get('singleBroadcast').value=message;
 try{const pending=JSON.parse(localStorage.getItem('balac-postimages-pending')||'null'),result=JSON.parse(localStorage.getItem('balac-postimages-result')||'null');if(pending&&result&&pending.id===result.id&&Date.now()-pending.createdAt<1800000){pendingId=pending.id;finish(result.id,result.message)}}catch{}
 window.BalacSharingHelpers={valid,extract};
})();
